# convert.py — thor_fp4.convert(model, policy): per-layer precision routing.
#
# FP4 on the Thor is shape-gated (measured; see BENCHMARKS.md): the NVFP4
# tensor-core kernels win on large-K GEMMs and lose on small-K ones even
# though the hardware rate is 2.5-4x BF16's — today's kernels are tuned for
# compute-bound shapes. So the default policy is shape-aware: FP4 where the
# measured per-shape table says it pays, BF16 elsewhere (e.g. a critic stays
# BF16). The table (src/thor_fp4/shape_table.json) is generated by
# benchmarks/bench_gemm.py on this box; a conservative fallback rule covers
# unlisted shapes.

from __future__ import annotations

import copy
import fnmatch
import json
from dataclasses import dataclass
from pathlib import Path

import torch
import torch.nn as nn

from .linear import Linear
from .quant import two_level_scale

__all__ = ["convert", "calibrate", "auto_decision", "load_shape_table", "shape_table_path"]

_TABLE = Path(__file__).resolve().parent / "shape_table.json"
_FALLBACK = {"min_k": 2048, "min_n": 512}


def shape_table_path() -> Path:
    return _TABLE


def load_shape_table() -> dict:
    if _TABLE.exists():
        return json.loads(_TABLE.read_text())
    return {"crossover": dict(_FALLBACK), "shapes": {}}


@dataclass
class Decision:
    spec: str          # "fp4" | "bf16"
    reason: str


def auto_decision(in_features: int, out_features: int, table: dict | None = None) -> Decision:
    """The shape-aware FP4/BF16 decision for a (K=in, N=out) linear layer."""
    table = table or load_shape_table()
    if in_features % 64 != 0:
        return Decision("bf16", f"K={in_features} not a multiple of 64 (scale tiles are 4 sf wide)")
    if out_features < 8 or out_features % 8 != 0:
        return Decision("bf16", f"N={out_features} violates the GEMM's N>=8, N%8==0 constraint")
    cross = table.get("crossover", _FALLBACK)
    key = f"{out_features}x{in_features}"
    if key in table.get("shapes", {}):
        # rows are per-batch: {"4096": {...}, "256": {...}}; the M=4096 row
        # is the serving case the crossover rule is derived from
        row = table["shapes"][key].get("4096") or next(iter(table["shapes"][key].values()))
        spec = "fp4" if row.get("fp4_wins", False) else "bf16"
        return Decision(spec, f"measured at M={row.get('m', 4096)}: fp4 {row['fp4_ms']:.4f} ms "
                              f"vs bf16 {row['bf16_ms']:.4f} ms (quantize included)")
    if in_features >= cross["min_k"] and out_features >= cross["min_n"]:
        return Decision("fp4", f"K={in_features} >= {cross['min_k']} and N={out_features} >= "
                               f"{cross['min_n']} (measured crossover)")
    return Decision("bf16", f"K={in_features} < {cross['min_k']} or N={out_features} < "
                            f"{cross['min_n']} (small-K shapes: FP4 kernels lose to BF16)")


def _match_policy(policy, name: str, module: nn.Module):
    """Resolve a policy to a spec ('fp4' | 'bf16' | 'auto') for one module."""
    if isinstance(policy, str):
        return policy
    if callable(policy):
        return policy(name, module)
    if isinstance(policy, dict):
        for pat, spec in policy.items():
            if fnmatch.fnmatch(name, pat) or name == pat:
                return spec
        return "auto"          # unmatched layers fall through to shape-aware
    raise TypeError(f"bad policy: {policy!r}")


@torch.no_grad()
def convert(model: nn.Module, policy="auto", calibration: dict | None = None,
            out_dtype: str = "f16", inplace: bool = False) -> nn.Module:
    """Replace nn.Linear layers per `policy`:

        policy="auto"          shape-aware: FP4 where the measured table wins
        policy="fp4"           every eligible Linear -> thor_fp4.Linear
        policy="bf16"          cast everything to BF16 (the critic case)
        policy={"critic.*": "bf16", "*": "auto"}
                               per-layer: fnmatch patterns on module names,
                               first match wins; values are specs; a callable
                               (name, module) -> spec works too

    `calibration` maps module names to static activation per-tensor scales
    (from thor_fp4.calibrate). Returns the converted model (a deep copy
    unless inplace=True) with `.thor_fp4_policy` recording each decision."""
    model = model if inplace else copy.deepcopy(model)
    table = load_shape_table()
    decisions: dict[str, str] = {}
    replaces: list[tuple[str, nn.Linear]] = []
    for name, m in model.named_modules():
        if isinstance(m, nn.Linear):
            spec = _match_policy(policy, name, m)
            if spec == "auto":
                spec = auto_decision(m.in_features, m.out_features, table).spec
            decisions[name] = spec
            if spec == "fp4":
                replaces.append((name, m))
    for name, m in replaces:
        try:
            new = Linear(m.in_features, m.out_features, bias=m.bias is not None,
                         out_dtype=out_dtype, device=m.weight.device)
            with torch.no_grad():
                new.weight.copy_(m.weight.detach().float())
                if m.bias is not None:
                    new.bias.copy_(m.bias.detach().float())
            if calibration and name in calibration:
                new.act_tensor_scale = float(calibration[name])
            _swap(model, name, new)
        except ValueError as e:
            decisions[name] = f"bf16 ({e})"
    # "bf16" decisions leave the layer unquantized in its original dtype;
    # callers who want the halved memory too can .to(torch.bfloat16) the model.
    model.thor_fp4_policy = decisions
    return model


def _swap(root: nn.Module, name: str, new: nn.Module):
    if "." in name:
        parent_name, attr = name.rsplit(".", 1)
        parent = root.get_submodule(parent_name)
    else:
        parent, attr = root, name
    setattr(parent, attr, new)


@torch.no_grad()
def calibrate(model: nn.Module, sample_inputs) -> dict:
    """Collect per-Linear activation amax on calibration data; returns the
    dict convert(policy=..., calibration=...) wants. sample_inputs is a
    tensor batch, a list of them, or a callable yielding batches."""
    amax: dict[int, float] = {}
    names: dict[int, str] = {}
    hooks = []
    for name, m in model.named_modules():
        if isinstance(m, nn.Linear):
            names[id(m)] = name
            def hook(mod, inp, out, _name=name):
                x = inp[0]
                a = x.abs().amax().item()
                amax[_name] = max(amax.get(_name, 0.0), a)
            hooks.append(m.register_forward_hook(hook))
    try:
        batches = sample_inputs() if callable(sample_inputs) else (
            sample_inputs if isinstance(sample_inputs, list) else [sample_inputs])
        for b in batches:
            model(b)
    finally:
        for h in hooks:
            h.remove()
    return {n: a / (6.0 * 448.0) for n, a in amax.items()}
